// ── Two Pointers: two-sum in sorted array ───────────────────────────
function twoSumSorted(nums, target) {
  let left = 0, right = nums.length - 1;
  while (left < right) {
    const sum = nums[left] + nums[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;   // pair is too small, advance left
    else              right--;  // pair is too large, retreat right
  }
  return []; // no pair found
}
console.log(twoSumSorted([1, 2, 4, 6, 8], 10)); // [2, 4]  (4+6)

// ── Sliding Window: longest substring without repeating chars ─────────
function lengthOfLongestSubstring(s) {
  const seen = new Map(); // char -> last index seen
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (seen.has(ch) && seen.get(ch) >= left) {
      // shrink: jump left past the previous occurrence
      left = seen.get(ch) + 1;
    }
    seen.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
console.log(lengthOfLongestSubstring('abcabcbb')); // 3  ('abc')
console.log(lengthOfLongestSubstring('pwwkew'));   // 3  ('wke')

// ── Fast/Slow Pointers: detect cycle ─────────────────────────────────
function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;        // tortoise: 1 step
    fast = fast.next.next;  // hare:     2 steps
    if (slow === fast) return true; // they met — cycle confirmed
  }
  return false; // fast fell off the end — no cycle
}

// ── Fast/Slow: find middle of linked list ─────────────────────────────
function findMiddle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
  }
  return slow; // when fast reaches end, slow is at the middle
}

// ── Prefix Sum with hash map: count subarrays summing to k ───────────
function subarraySum(nums, k) {
  const counts = new Map([[0, 1]]); // prefix-sum 0 seen once (before any element)
  let prefix = 0, total = 0;
  for (const n of nums) {
    prefix += n;
    // how many previous prefixes equal (prefix - k)?
    // those subarrays end here and sum to k
    total += counts.get(prefix - k) ?? 0;
    counts.set(prefix, (counts.get(prefix) ?? 0) + 1);
  }
  return total;
}
console.log(subarraySum([1, 1, 1], 2)); // 2  ([0..1] and [1..2])
console.log(subarraySum([1, 2, 3], 3)); // 2  ([0..1] and [2..2])

// ── Merge Intervals ──────────────────────────────────────────────────
function mergeIntervals(intervals) {
  intervals.sort((a, b) => a[0] - b[0]); // sort by start
  const merged = [intervals[0]];
  for (const [start, end] of intervals.slice(1)) {
    const last = merged[merged.length - 1];
    if (start <= last[1]) {
      last[1] = Math.max(last[1], end); // IMPORTANT: max, not just end
    } else {
      merged.push([start, end]);
    }
  }
  return merged;
}
console.log(JSON.stringify(mergeIntervals([[1,3],[2,6],[8,10],[15,18]])));
// [[1,6],[8,10],[15,18]]

// ── BFS: shortest path in unweighted graph ───────────────────────────
function bfsShortestPath(graph, start, end) {
  const visited = new Set([start]);
  const queue = [[start, 0]]; // [node, distance]
  while (queue.length) {
    const [node, dist] = queue.shift();
    if (node === end) return dist;
    for (const neighbor of (graph[node] ?? [])) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push([neighbor, dist + 1]);
      }
    }
  }
  return -1;
}
const g = { A: ['B','C'], B: ['D'], C: ['D'], D: [] };
console.log(bfsShortestPath(g, 'A', 'D')); // 2

// ── DFS: count islands in a grid (flood-fill) ────────────────────────
function numIslands(grid) {
  let count = 0;
  function dfs(r, c) {
    // bounds check and water/visited check
    if (r < 0 || r >= grid.length) return;
    if (c < 0 || c >= grid[0].length) return;
    if (grid[r][c] !== '1') return;
    grid[r][c] = '0'; // mark visited by mutating grid
    dfs(r + 1, c); dfs(r - 1, c);
    dfs(r, c + 1); dfs(r, c - 1);
  }
  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < grid[0].length; c++) {
      if (grid[r][c] === '1') {
        count++;
        dfs(r, c); // flood entire island
      }
    }
  }
  return count;
}
console.log(numIslands([['1','1','0'],['0','1','0'],['0','0','1']])); // 2

// ── Backtracking: all subsets ─────────────────────────────────────────
function subsets(nums) {
  const result = [];
  function bt(start, current) {
    result.push([...current]); // copy — do NOT push the reference
    for (let i = start; i < nums.length; i++) {
      current.push(nums[i]); // choose
      bt(i + 1, current);    // explore
      current.pop();          // unchoose
    }
  }
  bt(0, []);
  return result;
}
console.log(subsets([1, 2, 3]).length); // 8  (2^3)

// ── Backtracking: permutations ────────────────────────────────────────
function permutations(nums) {
  const result = [];
  function bt(start) {
    if (start === nums.length) { result.push([...nums]); return; }
    for (let i = start; i < nums.length; i++) {
      [nums[start], nums[i]] = [nums[i], nums[start]]; // choose: swap in
      bt(start + 1);
      [nums[start], nums[i]] = [nums[i], nums[start]]; // unchoose: swap back
    }
  }
  bt(0);
  return result;
}
console.log(permutations([1, 2, 3]).length); // 6  (3!)
